const NOTION_VERSION = '2022-06-28';
const ENV = typeof process !== 'undefined' && process.env ? process.env : {};
const DATABASE_ID = ENV.NOTION_CASES_DATABASE_ID || '330b3ad1d1cd8047aabfc9e95de6658d';
const NOTION_TOKEN = ENV.NOTION_API_TOKEN || '???NotionIntegrationToken';
const body = $('Admin Cases Webhook').first().json.body || {};
const action = String(body.action || 'cases.list').trim();
const data = body.data || {};

function response(ok, payload = {}, statusCode = 200) {
  return [{ json: ok ? { ok: true, data: payload } : { ok: false, statusCode, message: payload.message || '????????' } }];
}

if (!DATABASE_ID || DATABASE_ID.includes('???') || !NOTION_TOKEN || NOTION_TOKEN.includes('???')) {
  return response(false, { message: '???? NOTION_CASES_DATABASE_ID ? NOTION_API_TOKEN?' }, 500);
}

async function notion(path, options = {}) {
  const res = await fetch(`https://api.notion.com/v1${path}`, {
    method: options.method || 'GET',
    headers: { Authorization: `Bearer ${NOTION_TOKEN}`, 'Notion-Version': NOTION_VERSION, 'Content-Type': 'application/json' },
    body: options.body ? JSON.stringify(options.body) : undefined
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(json.message || `Notion API ${res.status}`);
  return json;
}

function rich(value) { return [{ type: 'text', text: { content: String(value || '') } }]; }
function truthy(value) { return value === true || value === 'true' || value === '1' || value === '__YES__' || value === '?' || value === '??'; }
function prop(page, name) {
  const p = page.properties?.[name];
  if (!p) return '';
  if (p.type === 'title') return (p.title || []).map((v) => v.plain_text || '').join('');
  if (p.type === 'rich_text') return (p.rich_text || []).map((v) => v.plain_text || '').join('');
  if (p.type === 'select') return p.select?.name || '';
  if (p.type === 'date') return p.date?.start || '';
  if (p.type === 'phone_number') return p.phone_number || '';
  if (p.type === 'checkbox') return p.checkbox ? 'true' : 'false';
  if (p.type === 'number') return p.number ?? '';
  if (p.type === 'files') return (p.files || []).map((v) => v.file?.url || v.external?.url || v.name).join(', ');
  if (p.type === 'created_time') return p.created_time || '';
  if (p.type === 'last_edited_time') return p.last_edited_time || '';
  if (p.type === 'formula') return p.formula?.string ?? p.formula?.number ?? p.formula?.boolean ?? '';
  return '';
}
function normalize(page) {
  return {
    id: page.id,
    caseNo: prop(page, '????'),
    requestDate: prop(page, '????'),
    createdAt: page.created_time || prop(page, '????'),
