  };
}
function selectProp(value) { return value ? { select: { name: String(value) } } : { select: null }; }
function phoneProp(value) { return value ? { phone_number: String(value) } : { phone_number: null }; }
function textProp(value) { return { rich_text: rich(value) }; }
function fileList(value) { return Array.isArray(value) ? value : String(value || '').split(',').map((url) => url.trim()).filter(Boolean); }
function filesProp(value) { return { files: fileList(value).map((url) => ({ name: url.split('/').pop() || 'image', type: 'external', external: { url } })) }; }
function propertiesFrom(input) {
  const props = {
    '????': { title: rich(input.caseNo || input.title || input.content || '???') },
    '????': selectProp(input.status),
    '????': { checkbox: truthy(input.isPublic) },
    '????': selectProp(input.area),
    '????': selectProp(input.category),
    '????': textProp(input.staff || input.ownerName || input.owner),
    '????': textProp(input.petitioner),
    '????': phoneProp(input.homePhone),
    '????': phoneProp(input.phone),
    '??Email': textProp(input.email),
    '????': textProp(input.address || input.mailingAddress),
    '????': textProp(input.householdAddress),
    '????': textProp(input.commissioner || input.principal),
    '??': textProp(input.relation),
    '????': textProp(input.content),
    '??????': textProp(input.inspectionNote || input.meetingRecord),
    '????': textProp(input.summary || input.publicSummary),
    '????': textProp(input.reply),
    '?????': filesProp(input.beforeImages),
    '?????': filesProp(input.afterImages)
  };
  props['????'] = input.requestDate || input.startDate ? { date: { start: input.requestDate || input.startDate } } : { date: null };
  if (input.processingDays !== '' && input.processingDays != null) {
    const value = Number(input.processingDays);
    props['????'] = { number: Number.isFinite(value) ? value : null };
  }
  return props;
}
function dateKey(value) { return String(value || '').slice(0, 10); }
async function listCases(filters = {}) {
  const out = [];
  let cursor;
  do {
    const result = await notion(`/databases/${DATABASE_ID}/query`, { method: 'POST', body: { page_size: 100, start_cursor: cursor, sorts: [{ property: '????', direction: 'descending' }] } });
    out.push(...(result.results || []));
    cursor = result.has_more ? result.next_cursor : null;
  } while (cursor);
  return out.map(normalize).filter((item) => {
    const date = dateKey(item.requestDate || item.createdAt);
    const keywordText = [item.caseNo, item.petitioner, item.phone, item.homePhone, item.email, item.content, item.summary, item.reply, item.staff, item.area, item.category].join(' ');
    return (!filters.caseNo || keywordText.includes(String(filters.caseNo).trim()))
      && (!filters.status || item.status === filters.status)
      && (!filters.category || item.category === filters.category)
      && (!filters.startDate || date >= filters.startDate)
      && (!filters.endDate || date <= filters.endDate);
  });
}
try {
  if (action === 'cases.list') return response(true, await listCases(body.filters || {}));
  if (action === 'cases.debugRaw') return response(true, { count: (await listCases(body.filters || {})).length });
  if (action === 'cases.create') {
    const page = await notion('/pages', { method: 'POST', body: { parent: { database_id: DATABASE_ID }, properties: propertiesFrom(data) } });
    return response(true, normalize(page));
  }
  if (action === 'cases.update') {
    if (!data.id) return response(false, { message: '???? page id?' }, 400);
    const page = await notion(`/pages/${data.id}`, { method: 'PATCH', body: { properties: propertiesFrom(data) } });
    return response(true, normalize(page));
  }
  if (action === 'cases.delete') {
    if (!body.id) return response(false, { message: '???? page id?' }, 400);
    await notion(`/pages/${body.id}`, { method: 'PATCH', body: { archived: true } });
    return response(true, { ok: true });
  }
  return response(false, { message: `???? action: ${action}` }, 400);
} catch (error) {
  return response(false, { message: error.message }, 500);
}
